defExports.burntIcosagon = {
    PARENT: [defExports.food],
    LABEL: 'Golden Icosagon',
    FOV: 1.5,
    VALUE: 6e5,
    SHAPE: -20,
    SIZE: 120,
    COLOR: 234, // 207
    BODY: {
        DAMAGE: 5,
        DENSITY: 110,
        HEALTH: 1750,
        RESIST: Math.pow(1.35, 3),
        SHIELD: 140,
        REGEN: .005
    },
    DRAW_HEALTH: true,
    GIVE_KILL_MESSAGE: true,
    GUNS: [{
        POSITION: [1, 5, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.no_recoil]),
            TYPE: defExports.egg,
            AUTOFIRE: true,
            MAX_CHILDREN: 1,
            ON_FIRE: (gun, gunInfo) => {
                if (gun.body.master.variables.bossSpawn === 2) {
                    gun.fire(gunInfo);
                    let child = undefined;
                    for (const c of gun.childrenMap.values()) {
                        child = c;
                    } child.define(Class.goldenMladicAI);
                    child.team = this.team
                    gun.body.master.variables.bossSpawn = 0
                }
            }
        }
    }, {
        POSITION: [1, 5, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.no_recoil]),
            TYPE: defExports.burntIcosagonRing,
            AUTOFIRE: true,
            ON_FIRE: (gun, gunInfo) => {
                if (gun.body.master.variables.bossSpawn === 1) {
                    gun.fire(gunInfo);
                }
            }
        }
    }],
    VARIABLES: {
        bossSpawn: 0
    },
    ON_DEFINED: (me, entities, sockets) => {
        setTimeout(() => {
            if (me && me.isAlive()) {
                sockets.broadcast("The Golden Icosagon is sending out messages, move away from it!");
                me.variables.bossSpawn++
                setTimeout(() => {
                    me.variables.bossSpawn++
                }, 7500)
            }
        }, 60000);
    }
};
