defExports.boomCrasher = {
    PARENT: [defExports.crushCrasher],
    LABEL: 'Explosive Crusher',
    SHAPE: 150,
    COLOR: 238,
    ON_DEAD: function({ sockets, ran, Entity }) {
        let x = this.x,
            y = this.y;
        for (let i = 0; i < 6; i++) {
            let crash = new Entity({
                x: x,
                y: y
            });
            crash.team = -100;
            crash.define(Class.boomCrusherShards14);
        }
        for (let i = 0; i < 2; i++) {
            let crash = new Entity({
                x: x,
                y: y
            });
            crash.team = -100;
            crash.define(Class.boomCrusherShards0);
        }
        for (let i = 0; i < 4; i++) {
            let crash = new Entity({
                x: x,
                y: y
            });
            crash.team = -100;
            crash.define(Class.boomCrusherShards);
        }
    },
    EVOLUTIONS: []
};
