defExports.sixShot = {
    PARENT: [defExports.genericTank],
    LABEL: 'Six-Shot',
    DANGER: 6,
    AMMO: 6,
    BODY: {
        ACCELERATION: base.ACCEL * .75,
        SPEED: base.SPEED * .95,
        FOV: 1.1
    },
    STAT_NAMES: statNames.generic,
    TOOLTIP: "Every six shots you will need to reload. 25% to land critical hits.",
    GUNS: [{
        POSITION: [28, 8, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.single, g.stronger, g.stronger, g.more_health, g.more_pen, g.more_speed, g.less_reload, g.bit_less_reload]),
            TYPE: defExports.bullet,
            AMMO_PER_SHOT: 1,
            ON_FIRE: function(gun, gunInfo) {
                gun.fire(gunInfo)
                const master = gun.body.master
                if (master.ammo == 0) {
                    master.displayText = "Reloading..."
                    setTimeout(() => {
                        master.ammo = 6
                        master.displayText = master.ammo + " Ammo left"
                    }, 3500)
                }
            },
            ON_DEALT_DAMAGE: function(me, them) {
                crit(me, them, 1.5, 25);
            }
        }
    }, {
        POSITION: [9, 8, -1.8, 6.5, 0, 0, 0]
    }],
};
