defExports.covert = {
    PARENT: [defExports.genericTank],
    LABEL: 'Covert',
    DANGER: 7,
    BODY: {
        FOV: 1.225,
        ACCELERATION: base.ACCEL * .7
    },
    ALPHA: 1,
    TOOLTIP: `Hold the alt-fire key to turn invisible; A powerful bullet will shoot once you turn fully invisible and let go!`,
    GUNS: [{
        POSITION: [20, 14.5, 1, 0, 0, 0, 0],
        PROPERTIES: {
            COLOR: 9
        }
    }, {
        POSITION: [24, 10.5, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.sniper, g.rifle, g.pound]),
            TYPE: defExports.bullet
        }
    }, {
        POSITION: [24, 10.5, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.sniper, g.rifle, g.pound, g.faster, g.more_pen, g.faster, g.more_pen]),
            TYPE: defExports.bullet,
            SKIN: 15,
            CAN_SHOOT: false
        }
    }, {
        POSITION: [20, 4, 1, 0, 0, 0, 0],
        PROPERTIES: {
            COLOR: 9
        }
    }],
    ON_MAIN: (me) => {
        if (me.alpha < 1) me.alpha += 0.05 * me.skill.rld;
    },
    ON_ALT: (me) => {
        if (me.alpha > 0.1) {
            me.alpha -= 0.025 / me.skill.rld;
        } else {
            me.onMain = undefined;
            me.guns[1].canShoot = false;
            me.onNotAlt = (me) => {
                me.onNotAlt = undefined;
                me.alpha = 1;
                fireGun(me.guns[2]);
                setTimeout(() => {
                    me.guns[1].canShoot = true;
                    me.onMain = (me) => {
                        if (me.alpha < 1) me.alpha += 0.05 * me.skill.rld;
                    };
                }, 1000);
            }
        }
    }
};
