defExports.doomsday = {
    PARENT: [defExports.genericTank],
    LABEL: 'Doomsday',
    TOOLTIP: 'Double click to make some of your drones explode!',
    DANGER: 7,
    GUNS: [{
        POSITION: diep2arras([70, 1, 1.75, 0, 0, 0, 0]),
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.drone, g.over, g.bigger, g.slow]),
            TYPE: defExports.doomsdayDrone,
            AUTOFIRE: true,
            SYNCS_SKILLS: true,
            STAT_CALCULATOR: gunCalcNames.drone,
            WAIT_TO_CYCLE: true,
            MAX_CHILDREN: 3
        }
    }, {
        POSITION: diep2arras([50, 2.3, 1, 0, 0, 0, 0])
    }, {
        POSITION: diep2arras([55, 2, 1, 0, 0, 0, 0])
    }, {
        POSITION: diep2arras([70, 1, 1.75, 0, 0, 180, 0]),
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.drone, g.over, g.bigger, g.bigger]),
            TYPE: defExports.drone,
            AUTOFIRE: true,
            SYNCS_SKILLS: true,
            STAT_CALCULATOR: gunCalcNames.drone,
            WAIT_TO_CYCLE: true,
            MAX_CHILDREN: 5
        }
    }],
    VARIABLES: {
        stage: 0,
        timer: Infinity
    },
    ON_MAIN: (me) => {
        if (me.variables.stage === 0) {
            me.variables.stage++;
        }

        if (me.variables.stage === 2) {
            if (Date.now() - me.variables.timer < 150) {
                while (me.guns[0].childrenMap.size > 0) {
                    me.guns[0].childrenMap.values().next().value.kill();
                }
            }

            me.variables.stage = 0;
        }
    },
    ON_NOT_MAIN: (me) => {
        if (me.variables.stage === 1) {
            me.variables.timer = Date.now();
            me.variables.stage++;

            setTimeout(() => {
                if (me.isAlive()) {
                    me.variables.stage = 0;
                }
            }, 150);
        }
    }
};
