defExports.afterimage = {
    PARENT: [defExports.genericTank],
    LABEL: "Afterimage",
    DANGER: 6,
    GUNS: [{
        POSITION: [12, 9, 1, 7.5, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.pound, [2, 1, 1, 1, 1.5, .8, 1, .8, .8, 1.5, 1, 1, 1]]),
            TYPE: defExports.afterimageBullet
        }
    }, {
        POSITION: [9, 9, 1, 7.5, 0, 0, 0],
        PROPERTIES: {
            COLOR: 8,
            SKIN: 3
        }
    }, {
        POSITION: [12, 14, 1, 0, 0, 0, 0],
        PROPERTIES: {
            COLOR: 9
        }
    }],
    VARIABLES: {
        lists: {}
    },
    ON_ALT: function(me) {
        for (const id in me.variables.lists) {
            me.variables.lists[id] = me.variables.lists[id].filter(bullet => bullet.isAlive());

            if (me.variables.lists[id].length === 0) {
                delete me.variables.lists[id];
                continue;
            }

            const i = me.variables.lists[id].length - 2;

            if (me.variables.lists[id][1] !== undefined) {
                me.variables.lists[id][1].passive = false;
                me.variables.lists[id][1].alpha = 1;
            }
        }
    }
};
